import { describe, it, expect } from "vitest";
import {
  decodeText, NUMBER_FORMAT, numberingErrorText, numberParts, suggestKey, validatePreassign, validateServiceLine,
} from "./billingNumbering";

// PV5-04b — the pure rules behind the service-line and number-code screens (PV-D35). Nothing here decides who may do what
// (Cerbos does) and nothing invents a code: a code is generated by the server, never derived in the browser.

describe("the number's shape", () => {
  it("is the one the owner ruled", () => {
    expect(NUMBER_FORMAT).toBe("{company}/{yyyy}/{mm}/{code}/{nnnn}");
  });

  it("splits an issued number into its parts, and answers null for an older one", () => {
    expect(numberParts("GDA/2026/10/7K3/0001")).toEqual({ prefix: "GDA", year: "2026", month: "10", code: "7K3", seq: "0001" });
    expect(numberParts("EX-1/2027/03/AB2/12345")).toMatchObject({ prefix: "EX-1", seq: "12345" });
    expect(numberParts("EX/2026/0001")).toBeNull();
    expect(numberParts(null)).toBeNull();
    expect(numberParts("")).toBeNull();
  });
});

describe("service line form", () => {
  it("a name and a well-formed key are needed", () => {
    expect(validateServiceLine({ key: "web_dev", name: "Web development" })).toBeNull();
    expect(validateServiceLine({ key: "web_dev", name: "  " })?.field).toBe("name");
    for (const key of ["", "x", "Web", "1abc", "web-dev", "a".repeat(33)]) {
      expect(validateServiceLine({ key, name: "Ok" })?.field, key).toBe("key");
    }
  });

  it("suggests a key from a name, always a valid one or empty", () => {
    expect(suggestKey("Web development")).toBe("web_development");
    expect(suggestKey("  SEO & Search  ")).toBe("seo_search");
    expect(suggestKey("24h support")).toBe("l_24h_support");
    expect(suggestKey("!!!")).toBe("");
    for (const n of ["Web development", "SEO & Search", "24h support", "x"]) {
      const k = suggestKey(n);
      expect(k === "" || /^[a-z][a-z0-9_]{0,31}$/.test(k), n).toBe(true);
    }
  });
});

describe("pre-assign form", () => {
  it("needs a line and a type; a code is optional but, when typed, 2 to 4 capital letters or digits", () => {
    expect(validatePreassign({ serviceLineKey: "web", businessType: "hotel", code: "" })).toBeNull();
    expect(validatePreassign({ serviceLineKey: "web", businessType: "hotel", code: "7K3" })).toBeNull();
    expect(validatePreassign({ serviceLineKey: "", businessType: "hotel", code: "" })?.field).toBe("serviceLineKey");
    expect(validatePreassign({ serviceLineKey: "web", businessType: "", code: "" })?.field).toBe("businessType");
    for (const code of ["a", "abc", "ABCDE", "A-B"]) {
      expect(validatePreassign({ serviceLineKey: "web", businessType: "hotel", code })?.field, code).toBe("code");
    }
  });
});

describe("decode and refusals", () => {
  it("decodes a number's code into the line and business type", () => {
    expect(decodeText({ serviceLineKey: "web", serviceLineName: "Web development", businessType: "hotel" }, "Hotel / villa")).toBe("Web development · Hotel / villa");
    expect(decodeText({ serviceLineKey: "web", serviceLineName: null, businessType: "hotel" })).toBe("web · hotel");
    expect(decodeText(null)).toBeNull();
  });

  it("puts the named 409 reasons in plain words", () => {
    expect(numberingErrorText(409, "code_already_assigned", "raw")).toMatch(/never changed/);
    expect(numberingErrorText(409, "code_taken", "raw")).toMatch(/another pair/);
    expect(numberingErrorText(409, "other", "raw message")).toBe("raw message");
    expect(numberingErrorText(403, undefined, "x")).toMatch(/finance managers/);
    expect(numberingErrorText(400, undefined, "bad code")).toBe("bad code");
  });
});
